public:
    Complex(float real, float imag) : _real(real), _imag(imag) {}

    Complex operator+(const Complex &c) const {
        return Complex(_real + c._real, _imag + c._imag);
    }

    Complex operator-(const Complex &c) const {
        return Complex(_real - c._real, _imag - c.

